import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import clsx from 'clsx';
import './AcidCalendar.css';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const DAYS = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];

export interface AcidCalendarProps {
    value?: Date;
    defaultValue?: Date;
    onChange?: (date: Date) => void;
    minDate?: Date;
    maxDate?: Date;
    className?: string;
}

export const AcidCalendar = ({
    value,
    defaultValue,
    onChange,
    minDate,
    maxDate,
    className
}: AcidCalendarProps) => {
    const today = new Date();
    const [internalDate, setInternalDate] = useState(defaultValue || null);
    const [viewDate, setViewDate] = useState(defaultValue || today);
    const [direction, setDirection] = useState(0);

    const selected = value !== undefined ? value : internalDate;

    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();

    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const daysInPrevMonth = new Date(year, month, 0).getDate();

    const cells: Array<{ day: number; type: 'prev' | 'current' | 'next' }> = [];
    for (let i = 0; i < firstDay; i++) {
        cells.push({ day: daysInPrevMonth - firstDay + 1 + i, type: 'prev' });
    }
    for (let i = 1; i <= daysInMonth; i++) {
        cells.push({ day: i, type: 'current' });
    }
    const remaining = 42 - cells.length;
    for (let i = 1; i <= remaining; i++) {
        cells.push({ day: i, type: 'next' });
    }

    const navigate = (dir: number) => {
        setDirection(dir);
        const next = new Date(viewDate);
        next.setMonth(next.getMonth() + dir);
        setViewDate(next);
    };

    const selectDay = (day: number, type: string) => {
        if (type !== 'current') return;
        const date = new Date(year, month, day);
        if (minDate && date < minDate) return;
        if (maxDate && date > maxDate) return;
        setInternalDate(date);
        onChange?.(date);
    };

    const isSelected = (day: number, type: string) => {
        if (!selected || type !== 'current') return false;
        return selected.getFullYear() === year && selected.getMonth() === month && selected.getDate() === day;
    };

    const isToday = (day: number, type: string) => {
        if (type !== 'current') return false;
        return today.getFullYear() === year && today.getMonth() === month && today.getDate() === day;
    };

    return (
        <div className={clsx('ac-calendar', className)}>
            <div className="ac-calendar-header">
                <button className="ac-calendar-nav" onClick={() => navigate(-1)}>
                    <ChevronLeft size={16} />
                </button>
                <AnimatePresence mode="wait" custom={direction}>
                    <motion.span
                        key={`${year}-${month}`}
                        className="ac-calendar-month-label"
                        custom={direction}
                        initial={{ opacity: 0, x: direction * 20 }}
                        animate={{ opacity: 1, x: 0 }}
                        exit={{ opacity: 0, x: direction * -20 }}
                        transition={{ duration: 0.2 }}
                    >
                        {MONTHS[month]} {year}
                    </motion.span>
                </AnimatePresence>
                <button className="ac-calendar-nav" onClick={() => navigate(1)}>
                    <ChevronRight size={16} />
                </button>
            </div>

            <div className="ac-calendar-grid">
                {DAYS.map(d => (
                    <div key={d} className="ac-calendar-day-label">{d}</div>
                ))}
                <AnimatePresence mode="wait" custom={direction}>
                    <motion.div
                        key={`${year}-${month}-cells`}
                        className="ac-calendar-cells"
                        custom={direction}
                        initial={{ opacity: 0, x: direction * 30 }}
                        animate={{ opacity: 1, x: 0 }}
                        exit={{ opacity: 0, x: direction * -30 }}
                        transition={{ duration: 0.2 }}
                    >
                        {cells.map((cell, i) => (
                            <button
                                key={i}
                                className={clsx(
                                    'ac-calendar-cell',
                                    cell.type !== 'current' && 'ac-calendar-cell-other',
                                    isToday(cell.day, cell.type) && 'ac-calendar-cell-today',
                                    isSelected(cell.day, cell.type) && 'ac-calendar-cell-selected'
                                )}
                                onClick={() => selectDay(cell.day, cell.type)}
                            >
                                {cell.day}
                            </button>
                        ))}
                    </motion.div>
                </AnimatePresence>
            </div>

            {selected && (
                <div className="ac-calendar-footer">
                    <span className="ac-calendar-selected-label">
                        SELECTED: {selected.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).toUpperCase()}
                    </span>
                </div>
            )}
        </div>
    );
};

.ac-calendar {
    display: inline-flex;
    flex-direction: column;
    border: 1px solid var(--ac-border-muted);
    background: var(--ac-surface);
    user-select: none;
    min-width: 300px;
}

.ac-calendar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
    border-bottom: 1px solid var(--ac-border-muted);
}

.ac-calendar-nav {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    background: transparent;
    border: 1px solid var(--ac-border-muted);
    color: var(--ac-text-secondary);
    cursor: pointer;
    transition: all 0.2s;
}

.ac-calendar-nav:hover {
    border-color: var(--ac-border-bright);
    color: var(--ac-text-primary);
    background: var(--ac-surface-hover);
}

.ac-calendar-month-label {
    font-family: var(--font-mono);
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.1em;
    color: var(--ac-text-primary);
}

.ac-calendar-grid {
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0;
}

.ac-calendar-day-label {
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-mono);
    font-size: 0.65rem;
    letter-spacing: 0.12em;
    color: var(--ac-text-muted);
    padding: 0.3rem;
}

/* We need 7 columns */
.ac-calendar-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    position: relative;
}

.ac-calendar-cells {
    display: contents;
}

.ac-calendar-cell {
    display: flex;
    align-items: center;
    justify-content: center;
    aspect-ratio: 1;
    background: transparent;
    border: none;
    color: var(--ac-text-primary);
    font-family: var(--font-mono);
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.15s ease;
    padding: 0;
}

.ac-calendar-cell:hover {
    background: var(--ac-surface-hover);
    color: var(--ac-text-primary);
}

.ac-calendar-cell-other {
    color: var(--ac-text-muted);
    cursor: default;
}

.ac-calendar-cell-other:hover {
    background: transparent;
}

.ac-calendar-cell-today {
    color: var(--ac-brand);
    font-weight: 700;
    position: relative;
}

.ac-calendar-cell-today::after {
    content: '';
    position: absolute;
    bottom: 4px;
    left: 50%;
    transform: translateX(-50%);
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--ac-brand);
}

.ac-calendar-cell-selected {
    background: var(--ac-text-primary) !important;
    color: var(--ac-bg) !important;
}

.ac-calendar-footer {
    padding: 0.75rem 1.25rem;
    border-top: 1px solid var(--ac-border-muted);
}

.ac-calendar-selected-label {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    letter-spacing: 0.08em;
    color: var(--ac-text-muted);
}
